// The horse's clip registry (its own: the hero's registry, ../../clips/index.js, decodes on the hero's
// skeleton). The sets in the reference's order: the MOVE film's riding chapters, then the SWORD film's.
// The set files are GENERATED by scripts/mocap/horse/gen.mjs.
import { createHorseLibrary } from '../hclip.js';

export const HORSE_SETS = [
  ['horseMove', () => import('./horseMove.js')], // MOVE 25:21-29:39
  ['horseSword', () => import('./horseSword.js')], // SWORD 7:02-8:40
];

/** Load every set (a failing set costs only its own clips) and decode them in order. */
export async function loadHorseLibrary(sets = HORSE_SETS) {
  const mods = [], failed = [];
  for (const [id, load] of sets) {
    try {
      mods.push(await load());
    } catch (e) {
      failed.push({ clip: '', text: `set ${id} failed to load: ${e?.message ?? e}` });
    }
  }
  const lib = createHorseLibrary(mods);
  lib.problems.unshift(...failed);
  return lib;
}
